<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {api} from '@/api/client'
import {skillAuthoring,type SkillDraft,type DraftRecord} from '@/api/skillAuthoring'
import {runnerProfiles,type ToolCatalog} from '@/api/runnerProfiles'
import type {Skill} from '@/api/skills'
import {renderMarkdown} from '@/shared/markdown'
const props=defineProps<{skill:Skill|null}>()
const emit=defineEmits<{close:[];saved:[]}>()
const draft=ref<SkillDraft>({name:'',description:'',version:'1.0.0',instructions:'',resources:{},tools:[],surfaces:['reader_chat']})
const record=ref<DraftRecord|null>(null),surfaces=ref<{id:string;label:string}[]>([]),catalog=ref<ToolCatalog|null>(null),error=ref(''),notice=ref(''),busy=ref(false),resourceJson=ref('{}'),preview=ref(false),scopeRevision=ref(0)
const nameRevision=ref(props.skill?.revision)
const copy=ref(props.skill?.source==='builtin')
onMounted(async()=>{busy.value=true;try{const [s,t]=await Promise.all([skillAuthoring.surfaces(),runnerProfiles.tools()]);surfaces.value=s.surfaces;catalog.value=t;if(props.skill){const [d,p]=await Promise.all([skillAuthoring.draft(props.skill.id),skillAuthoring.placements(props.skill.id)]);draft.value=d.body;record.value=copy.value?null:d;scopeRevision.value=p.revision;resourceJson.value=JSON.stringify(d.body.resources,null,2)}}catch(e){error.value=String(e)}finally{busy.value=false}})
async function save(publish=false){busy.value=true;error.value='';notice.value='';try{const resources=JSON.parse(resourceJson.value);if(!resources||Array.isArray(resources)||typeof resources!=='object')throw Error('资源需为路径到文本的 JSON 对象');const d=await skillAuthoring.save({...draft.value,resources},record.value?.skill_id,record.value?.revision);record.value=d;if(publish){await skillAuthoring.publish(d.skill_id,d.revision);notice.value='版本已发布，启用后可选择运行。'}else notice.value='草稿已保存';emit('saved')}catch(e){error.value=String(e)}finally{busy.value=false}}
async function metadata(){if(!props.skill)return;busy.value=true;try{const updated=await api<Skill>('/api/skills/'+encodeURIComponent(props.skill.id),{method:'PATCH',body:{name:draft.value.name,description:draft.value.description,expected_revision:nameRevision.value}});nameRevision.value=updated.revision;await skillAuthoring.setPlacements(props.skill.id,draft.value.surfaces,scopeRevision.value);scopeRevision.value=(await skillAuthoring.placements(props.skill.id)).revision;notice.value='显示名和范围已保存';emit('saved')}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><div class="designer-overlay"><section class="designer" role="dialog" aria-modal="true" aria-label="设计 Skill"><header><h2>{{skill?'配置与设计 Skill':'新建 Skill'}}</h2><button @click="emit('close')">关闭</button></header><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><label>显示名<input v-model="draft.name" maxlength="120"/></label><label>简介<input v-model="draft.description" maxlength="1000"/></label><fieldset><legend>展示并可用于</legend><label v-for="s in surfaces" :key="s.id" class="check"><input type="checkbox" v-model="draft.surfaces" :value="s.id"/>{{s.label}}</label></fieldset><button v-if="skill" :disabled="busy" @click="metadata">保存显示名与使用范围</button><p v-if="copy">内置指令将复制为独立的自定义 Skill。</p><label>发布版本<input v-model="draft.version" maxlength="40"/></label><label>Skill 指令<textarea v-model="draft.instructions" rows="12" maxlength="100000"/></label><button @click="preview=!preview">{{preview?'隐藏预览':'预览指令'}}</button><div v-if="preview" class="markdown-content" v-html="renderMarkdown(draft.instructions)"></div><details><summary>资源与工具</summary><label>资源（JSON：相对路径 → 文本）<textarea v-model="resourceJson" rows="6"/></label><label v-for="t in catalog?.servers.flatMap(s=>s.tools)||[]" :key="t.name" class="check"><input type="checkbox" v-model="draft.tools" :value="t.name"/>{{t.name}}</label></details><footer><button :disabled="busy||!draft.name.trim()||!draft.instructions.trim()" @click="save()">保存草稿</button><button :disabled="busy||!draft.name.trim()||!draft.instructions.trim()" @click="save(true)">保存并发布</button></footer></section></div></template>
<style scoped>.designer-overlay{position:fixed;inset:0;background:#0006;z-index:90;display:grid;place-items:center;padding:24px}.designer{width:min(820px,100%);max-height:90dvh;overflow:auto;background:var(--bg);border:1px solid var(--border);border-radius:12px;padding:24px;box-sizing:border-box}.designer header,.designer footer{display:flex;align-items:center;justify-content:space-between;gap:12px}.designer label{display:grid;gap:6px;margin:12px 0}.designer .check{display:inline-flex;align-items:center;margin:6px 12px 6px 0}.designer input:not([type=checkbox]),.designer textarea{padding:8px;width:100%;box-sizing:border-box}.designer [role=alert]{color:var(--danger)}.designer footer{margin-top:20px}</style>
